import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Connect Ershu to an MCP client","description":"Create a scoped MCP key, connect a client to Ershu, and follow a verifiable tool sequence into project context.","frontmatter":{"page_id":"guide-connect-mcp","description":"Create a scoped MCP key, connect a client to Ershu, and follow a verifiable tool sequence into project context."},"headers":[],"relativePath":"en/guide/connect-mcp.md","filePath":"en/guide/connect-mcp.md","lastUpdated":1786290726000}'),c={name:"en/guide/connect-mcp.md"};function d(i,e,n,s,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="connect-ershu-to-an-mcp-client" tabindex="-1">Connect Ershu to an MCP client <a class="header-anchor" href="#connect-ershu-to-an-mcp-client" aria-label="Permalink to &quot;Connect Ershu to an MCP client&quot;">​</a></h1><p>Ershu MCP is a read-only entry point for development agents. It does not modify repositories or generate documents. It exposes Core project, permission, document, index, and graph queries while applying both user permissions and the MCP key scope to every request.</p><p>This page is client-neutral. Client configuration fields differ, but the required connection information is the same.</p><h2 id="confirm-three-prerequisites" tabindex="-1">Confirm three prerequisites <a class="header-anchor" href="#confirm-three-prerequisites" aria-label="Permalink to &quot;Confirm three prerequisites&quot;">​</a></h2><ol><li>The MCP process is running. Its default endpoint is <code>http://127.0.0.1:8001/mcp/</code>.</li><li>You can already read the target project in the Ershu web interface. A key never expands your project permissions.</li><li>The target repository has the facts you need. A tree can be read from the current source, while code indexes, relationships, and documents depend on analysis and refresh state.</li></ol><p>You can open <code>http://127.0.0.1:8001/health</code> first. A <code>{&quot;status&quot;:&quot;ok&quot;}</code> response only proves that the process is alive; it does not prove database access, authorization, or tool execution.</p><h2 id="create-a-least-privilege-key" tabindex="-1">Create a least-privilege key <a class="header-anchor" href="#create-a-least-privilege-key" aria-label="Permalink to &quot;Create a least-privilege key&quot;">​</a></h2><p>When creating a key in the Ershu MCP key page, provide a name and choose one scope:</p><ul><li>one or more explicit projects; or</li><li>every project currently readable by the user.</li></ul><p>You may also set a future expiration time. A safer default is to select only the projects required for the current task and set an expiry. The service returns the full key only in the create response. Later listings retain only its prefix, scope, expiry, and usage metadata, so save it in the client&#39;s secret store when it is created.</p><p>Calls are rejected after the key is revoked or expires, or when the original user loses permission to the project. Creation and revocation are recorded in the audit log.</p><h2 id="enter-the-client-connection-details" tabindex="-1">Enter the client connection details <a class="header-anchor" href="#enter-the-client-connection-details" aria-label="Permalink to &quot;Enter the client connection details&quot;">​</a></h2><p>Map the following values into the client&#39;s Streamable HTTP settings. Use that client&#39;s documentation for exact field names instead of assuming one fixed JSON shape.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Transport</td><td>Streamable HTTP</td></tr><tr><td>Endpoint</td><td><code>http://127.0.0.1:8001/mcp/</code></td></tr><tr><td>Request header</td><td><code>Authorization: Bearer &lt;MCP_KEY&gt;</code></td></tr></tbody></table><p>Use HTTPS in production and proxy <code>/mcp/</code> unchanged to MCP port <code>8001</code>. Add the external Host and Origin to <code>MCP_ALLOWED_HOSTS</code> and <code>MCP_ALLOWED_ORIGINS</code>. Do not send MCP traffic to API port <code>8000</code>.</p><h2 id="validate-the-first-call-with-get-server-info" tabindex="-1">Validate the first call with <code>get_server_info</code> <a class="header-anchor" href="#validate-the-first-call-with-get-server-info" aria-label="Permalink to &quot;Validate the first call with `get_server_info`&quot;">​</a></h2><p>Call <code>get_server_info</code> immediately after connecting. A successful result includes:</p><ul><li><code>service</code>, currently <code>ershu-mcp</code>;</li><li>the installed package version;</li><li>the exact source commit used for the build;</li><li><code>identity_status</code>; and</li><li>the registered tool names.</li></ul><p>A production process refuses to start unless its package version is readable and <code>MCP_BUILD_COMMIT</code> is an exact 40-character commit. Development may omit either value; in that case <code>identity_status</code> is <code>unavailable</code>, so the build identity has not been verified.</p><p>The current service should report 27 tools. If the connection succeeds but no tools appear, or the list differs from the expected build, inspect the service version and proxy path before relying on it.</p><h2 id="follow-a-reliable-reading-sequence" tabindex="-1">Follow a reliable reading sequence <a class="header-anchor" href="#follow-a-reliable-reading-sequence" aria-label="Permalink to &quot;Follow a reliable reading sequence&quot;">​</a></h2><p>A project reference may be a UUID, slug, or unique readable name. Use a slug or UUID when names are ambiguous.</p><ol><li>Call <code>list_projects</code> to discover what the key can see.</li><li>Call <code>resolve_project</code>, then <code>list_project_repositories</code> to obtain repository identifiers and freshness.</li><li>Use <code>get_project_overview</code> for orientation, then <code>list_repository_documents</code> and <code>list_document_sections</code> to select a document section.</li><li>Use <code>list_repository_tree</code> and <code>list_repository_code_index</code> to find source paths and symbols.</li><li>Narrow the area with <code>find_project_change_surface</code> or <code>trace_project_runtime_flow</code>.</li><li>Finish with <code>read_code_context</code> to verify exact behavior in source.</li></ol><p>A document may carry <code>authority: secondary</code>, making it useful for navigation and explanation. Source, contract, and structured fact results use <code>source_derived</code> authority and are more suitable for exact claims. Always inspect the commit, freshness, coverage, and truncation metadata as well.</p><h2 id="how-the-27-tools-are-grouped" tabindex="-1">How the 27 tools are grouped <a class="header-anchor" href="#how-the-27-tools-are-grouped" aria-label="Permalink to &quot;How the 27 tools are grouped&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Tools</th></tr></thead><tbody><tr><td>Service and project discovery</td><td><code>get_server_info</code>, <code>list_projects</code>, <code>resolve_project</code>, <code>list_project_repositories</code></td></tr><tr><td>Fact refresh and run tracking</td><td><code>refresh_repository_facts</code>, <code>get_run_status</code></td></tr><tr><td>Project documents</td><td><code>get_project_overview</code>, <code>list_repository_documents</code>, <code>list_document_sections</code>, <code>get_document</code>, <code>get_document_section</code></td></tr><tr><td>Source and index navigation</td><td><code>list_repository_tree</code>, <code>list_repository_code_index</code>, <code>read_code_context</code></td></tr><tr><td>Search and relationship analysis</td><td><code>search_project_context</code>, <code>query_internal_api</code>, <code>query_project_graph</code>, <code>find_project_change_surface</code>, <code>trace_project_runtime_flow</code></td></tr><tr><td>Consumer contracts</td><td><code>list_project_contracts</code>, <code>get_consumer_contract</code>, <code>list_public_interfaces</code>, <code>get_public_interface</code>, <code>get_contract_schema</code>, <code>query_consumer_contracts</code>, <code>diff_consumer_contracts</code>, <code>suggest_consumer_work</code></td></tr></tbody></table><p>Paged tools generally accept a <code>limit</code> from <code>1</code> to <code>100</code> and a zero-based offset. Tree depth is capped at <code>10</code>, one tree response retains at most <code>500</code> entries, and one source read is capped at <code>400</code> lines. The effective service limit for consumer-contract queries is <code>50</code>. These bounds protect context size; they do not make a result exhaustive.</p><h2 id="refresh-facts-only-when-needed" tabindex="-1">Refresh facts only when needed <a class="header-anchor" href="#refresh-facts-only-when-needed" aria-label="Permalink to &quot;Refresh facts only when needed&quot;">​</a></h2><p>If repository freshness is stale and the current user can maintain the project, call <code>refresh_repository_facts</code>. It enqueues exactly four kinds of work:</p><ul><li>repository tree;</li><li>code index;</li><li>knowledge graph; and</li><li>search index.</li></ul><p>It does not generate or rewrite AI documents. After the tool returns a run identifier, observe queued, running, completed, or failed state with <code>get_run_status</code>. A status query never creates another run.</p><h2 id="diagnose-common-connection-failures" tabindex="-1">Diagnose common connection failures <a class="header-anchor" href="#diagnose-common-connection-failures" aria-label="Permalink to &quot;Diagnose common connection failures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check first</th></tr></thead><tbody><tr><td><code>401</code> or an authentication error</td><td>The header uses the exact <code>Bearer</code> scheme; the key is complete, unexpired, and not revoked</td></tr><tr><td>Project not found</td><td>Key scope, user project permission, and whether the readable name is ambiguous</td></tr><tr><td><code>/health</code> opens but the client cannot connect</td><td>The client uses <code>/mcp/</code>, the proxy preserves that path, and Host and Origin are allowed</td></tr><tr><td>Search reports degraded quality</td><td>Retrieval mode, <code>degraded</code>, <code>fallback_used</code>, and search-index state</td></tr><tr><td>A relationship result is unexpectedly small</td><td><code>data_status</code>, coverage, limits, and truncation; a bounded candidate set is not exhaustive</td></tr><tr><td>Documents disagree with source</td><td>Document commit and <code>authority</code>, followed by verification through <code>read_code_context</code></td></tr></tbody></table><p>The final success criterion is not the health page. The client must authenticate <code>get_server_info</code>, list a project you genuinely have permission to read, and return a tree or source result that includes repository revision information.</p><blockquote><p>Primary source locations: <code>mcp/src/ershu/mcp/server.py</code>, <code>mcp/src/ershu/mcp/tool_runtime.py</code>, <code>mcp/src/ershu/mcp/runtime_identity.py</code>, and <code>api/src/ershu/api/services/mcp_keys.py</code>.</p></blockquote>',35)])])}const m=t(c,[["render",d]]);export{p as __pageData,m as default};
